// @FIGURE_CODE_BEGIN
(function () {
  var container = document.getElementById('container');
  var draw = SVG().addTo(container).size('100%', '100%');
  var W = 1060, H = 730, OY = 365, R = 21;
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var GRAY = '#d4d4d4', AC = '#e07b00', GRN = '#1a9641';

  var BASE = [
    { k: 23, x: 120, y: 110, m: 0, p: null },
    { k: 7, x: 250, y: 110, m: 0, p: null },
    { k: 3, x: 470, y: 110, m: 0, p: null },
    { k: 17, x: 730, y: 110, m: 0, p: null },
    { k: 24, x: 895, y: 110, m: 0, p: null },
    { k: 18, x: 385, y: 210, m: 1, p: 3 },
    { k: 52, x: 470, y: 210, m: 0, p: 3 },
    { k: 38, x: 555, y: 210, m: 0, p: 3 },
    { k: 39, x: 385, y: 300, m: 1, p: 18 },
    { k: 41, x: 555, y: 300, m: 0, p: 38 },
    { k: 30, x: 730, y: 210, m: 0, p: 17 },
    { k: 26, x: 855, y: 210, m: 1, p: 24 },
    { k: 46, x: 940, y: 210, m: 0, p: 24 },
    { k: 35, x: 855, y: 300, m: 0, p: 26 }
  ];
  BASE.forEach(function (n) { n.id = n.k; });

  var CHILDPTR = { 3: 52, 18: 39, 38: 41, 17: 30, 24: 26, 26: 35 };
  var CHILDGROUPS = [[18, 52, 38], [39], [41], [30], [26, 46], [35]];

  var state = { mode: 'both', inserted: false, phase: 0, key: 21, selected: null, fade: false };
  var fadeEls = [];
  var running = false;

  /* ---------- model helpers ---------- */
  function newNodeObj() {
    return { k: state.key, x: 1000, y: (state.phase === 1 ? 42 : 110), m: 0, p: null, id: 'new' };
  }
  function allNodes() {
    var a = BASE.slice();
    if (state.inserted) a.push(newNodeObj());
    return a;
  }
  function byId(id) {
    var a = allNodes();
    for (var i = 0; i < a.length; i++) if (a[i].id === id) return a[i];
    return null;
  }
  function rootGroup() {
    var g = [23, 7, 3, 17, 24];
    if (state.inserted && state.phase >= 2) g.push('new');
    return g;
  }
  function minRootId() {
    if (state.inserted && state.phase >= 3 && state.key < 3) return 'new';
    return 3;
  }
  function siblingGroupOf(id) {
    var gs = [rootGroup()].concat(CHILDGROUPS);
    if (state.inserted && state.phase === 1) gs.push(['new']);
    for (var i = 0; i < gs.length; i++) if (gs[i].indexOf(id) >= 0) return gs[i];
    return [id];
  }
  function childListOf(id) {
    var out = [];
    BASE.forEach(function (n) { if (n.p === id) out.push(n.k); });
    return out;
  }

  /* ---------- primitive drawing helpers ---------- */
  function arrow(g, x1, y1, x2, y2, o) {
    o = o || {};
    var col = o.color || '#111', w = o.width || 1.7, hs = o.head || 8;
    var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
    var ux = dx / L, uy = dy / L;
    var ln = g.line(x1, y1, x2 - ux * hs * 0.85, y2 - uy * hs * 0.85)
      .stroke({ color: col, width: w, linecap: 'round' });
    if (o.dashed) ln.attr('stroke-dasharray', '7,6');
    var px = -uy, py = ux;
    g.polygon([
      [x2, y2],
      [x2 - ux * hs + px * hs * 0.5, y2 - uy * hs + py * hs * 0.5],
      [x2 - ux * hs - px * hs * 0.5, y2 - uy * hs - py * hs * 0.5]
    ].map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(col);
    return ln;
  }
  function triR(g, x, y, s, col) {
    return g.polygon([[x, y], [x - s, y - s * 0.62], [x - s, y + s * 0.62]]
      .map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(col);
  }
  function triL(g, x, y, s, col) {
    return g.polygon([[x, y], [x + s, y - s * 0.62], [x + s, y + s * 0.62]]
      .map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(col);
  }
  function lbl(g, x, y, s, col, size) {
    var t = g.text(s).font({
      family: 'Georgia, "Times New Roman", serif', size: size || 13,
      style: 'italic', anchor: 'middle'
    }).fill(col || '#000');
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.6, 'stroke-linejoin': 'round' });
    t.center(x, y);
    return t;
  }
  function ptrArrow(g, ax, ay, bx, by, off, col, w) {
    var dx = bx - ax, dy = by - ay, L = Math.sqrt(dx * dx + dy * dy) || 1;
    var ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
    var sx = ax + ux * (R + 2) + nx * off, sy = ay + uy * (R + 2) + ny * off;
    var ex = bx - ux * (R + 2) + nx * off, ey = by - uy * (R + 2) + ny * off;
    return arrow(g, sx, sy, ex, ey, { color: col || '#111', width: w || 1.7, head: 8 });
  }

  /* ---------- nodes ---------- */
  function drawNode(g, n) {
    var ng = g.group();
    var isNew = (n.id === 'new');
    ng.circle(2 * R).center(n.x, n.y)
      .fill(n.m ? '#111' : GRAY)
      .stroke({ color: isNew ? GRN : '#222', width: isNew ? 2.6 : 1.6 });
    ng.text(String(n.k)).font({
      family: 'Helvetica, Arial, sans-serif', size: 17,
      weight: n.m ? 'bold' : 'normal', anchor: 'middle'
    }).fill(n.m ? '#fff' : '#000').center(n.x, n.y);
    ng.css('cursor', 'pointer');
    var kids = isNew ? [] : childListOf(n.id);
    var tip = 'key ' + n.k + (n.m ? ' — marked (lost a child)' : ' — unmarked') +
      (isNew ? ' — newly inserted root' : (n.p == null ? ' — root' : ' — child of ' + n.p)) +
      (kids.length ? '; children ' + kids.join(', ') : '; no children');
    ng.on('mousemove', function (e) { showTooltip(tip, e); });
    ng.on('mouseleave', function () { hideTooltip(); });
    ng.on('click', function (e) { e.stopPropagation(); selectNode(n.id); });
    if (isNew) fadeEls.push(ng);
    return ng;
  }

  /* ---------- rails (circular doubly linked lists) ---------- */
  function railGeom(ids) {
    var ns = ids.map(byId).filter(function (n) { return !!n; });
    if (!ns.length) return null;
    var xs = ns.map(function (n) { return n.x; });
    var mn = Math.min.apply(null, xs), mx = Math.max.apply(null, xs), y = ns[0].y;
    return {
      y: y, ns: ns,
      up: { x: mn - 44, w: (mx + 34) - (mn - 44), y: y - 37, h: 31, r: 15 },
      lo: { x: mn - 34, w: (mx + 44) - (mn - 34), y: y + 6, h: 31, r: 15 }
    };
  }
  function drawRail(g, ids) {
    var gm = railGeom(ids);
    if (!gm) return;
    var up = g.rect(gm.up.w, gm.up.h).move(gm.up.x, gm.up.y).radius(gm.up.r)
      .fill('none').stroke({ color: '#111', width: 1.5 });
    var lo = g.rect(gm.lo.w, gm.lo.h).move(gm.lo.x, gm.lo.y).radius(gm.lo.r)
      .fill('none').stroke({ color: '#111', width: 1.5 });
    up.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('right pointers — the loop wraps from the last sibling back to the first', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function (e) {
        e.stopPropagation();
        showPopup('Circular doubly linked sibling list',
          'Each sibling group is stored as a circular doubly linked list: the upper rail carries the right pointers, the lower rail the left pointers. Because the list is circular there is no head or tail to special-case, so inserting or removing a node is four pointer assignments.');
      });
    lo.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('left pointers — the same list traversed backwards', e); })
      .on('mouseleave', hideTooltip);
    gm.ns.forEach(function (n) {
      var col = (n.id === 'new' && state.phase >= 2) ? GRN : '#111';
      var a = triR(g, n.x - 20, gm.y - 6, 8, col);
      var b = triL(g, n.x + 20, gm.y + 6, 8, col);
      if (col === GRN) { fadeEls.push(a); fadeEls.push(b); }
    });
  }

  /* ---------- panel (a) ---------- */
  function drawA(g) {
    var b23 = byId(23), b24 = byId(24);
    g.line(b23.x, 110, b24.x, 110).stroke({ color: '#000', width: 1.6 })
      .attr('stroke-dasharray', '9,7');
    if (state.inserted && state.phase >= 2) {
      var nn = byId('new');
      fadeEls.push(g.line(b24.x, 110, nn.x, 110)
        .stroke({ color: GRN, width: 2.2 }).attr('stroke-dasharray', '7,6'));
    }
    BASE.forEach(function (n) {
      if (n.p != null) {
        var p = byId(n.p);
        g.line(p.x, p.y, n.x, n.y).stroke({ color: '#333', width: 1.6 });
      }
    });
    var mn = byId(minRootId());
    lbl(g, mn.x, 30, 'H.min', '#000', 19);
    arrow(g, mn.x, 44, mn.x, 110 - R - 5, { color: '#000', width: 2.1, head: 10 });
    g.text('(a)').font({ family: 'Georgia, serif', size: 22, anchor: 'middle' })
      .fill('#000').center(42, 110);
    var list = BASE.slice();
    if (state.inserted) list.push(byId('new'));
    list.forEach(function (n) { drawNode(g, n); });
    if (state.selected != null) {
      var s = byId(state.selected);
      if (s) g.circle(2 * (R + 7)).center(s.x, s.y).fill('none').stroke({ color: AC, width: 2.5 });
    }
  }

  /* ---------- panel (b) ---------- */
  function drawB(g) {
    var groups = [rootGroup()].concat(CHILDGROUPS);
    if (state.inserted && state.phase === 1) groups.push(['new']);
    groups.forEach(function (ids) { drawRail(g, ids); });

    Object.keys(CHILDPTR).forEach(function (pid) {
      var p = byId(+pid), c = byId(CHILDPTR[+pid]);
      if (p && c) ptrArrow(g, p.x, p.y, c.x, c.y, 7, '#111', 1.7);
    });
    BASE.forEach(function (n) {
      if (n.p != null) ptrArrow(g, n.x, n.y, byId(n.p).x, byId(n.p).y, 7, '#111', 1.7);
    });

    var mn = byId(minRootId());
    lbl(g, mn.x, 30, 'H.min', '#000', 19);
    arrow(g, mn.x, 44, mn.x, 70, { color: '#000', width: 2.1, head: 10 });
    g.text('(b)').font({ family: 'Georgia, serif', size: 22, anchor: 'middle' })
      .fill('#000').center(42, 110);

    var list = BASE.slice();
    if (state.inserted) list.push(byId('new'));
    list.forEach(function (n) { drawNode(g, n); });

    drawHighlight(g);
  }

  /* ---------- pointer highlight (x.p, x.child, x.left, x.right) ---------- */
  function drawHighlight(g) {
    var id = state.selected;
    if (id == null) return;
    var n = byId(id);
    if (!n) return;
    g.circle(2 * (R + 8)).center(n.x, n.y).fill('none').stroke({ color: AC, width: 3 });

    if (n.p != null) {
      var par = byId(n.p);
      ptrArrow(g, n.x, n.y, par.x, par.y, 16, AC, 2.4);
      lbl(g, (n.x + par.x) / 2 + 36, (n.y + par.y) / 2, 'x.p', AC, 14);
    } else {
      lbl(g, n.x + 74, n.y - 54, 'x.p = NIL', AC, 13);
    }

    var cid = (n.id === 'new') ? null : CHILDPTR[n.id];
    if (cid != null) {
      var c = byId(cid);
      ptrArrow(g, n.x, n.y, c.x, c.y, -16, AC, 2.4);
      lbl(g, (n.x + c.x) / 2 - 40, (n.y + c.y) / 2, 'x.child', AC, 14);
    } else {
      lbl(g, n.x - 4, n.y + 66, 'x.child = NIL', AC, 13);
    }

    var grp = siblingGroupOf(id), i = grp.indexOf(id), len = grp.length;
    var gm = railGeom(grp);
    if (!gm) return;
    if (len === 1) {
      g.rect(gm.up.w, gm.up.h).move(gm.up.x, gm.up.y).radius(gm.up.r)
        .fill('none').stroke({ color: AC, width: 2.6 });
      g.rect(gm.lo.w, gm.lo.h).move(gm.lo.x, gm.lo.y).radius(gm.lo.r)
        .fill('none').stroke({ color: AC, width: 2.6 });
      lbl(g, n.x, gm.up.y - 12, 'x.right = x', AC, 13);
      lbl(g, n.x, gm.lo.y + gm.lo.h + 12, 'x.left = x', AC, 13);
      return;
    }
    var rn = byId(grp[(i + 1) % len]);
    if (i < len - 1 && rn) {
      g.line(n.x + 20, gm.y - 6, rn.x - 28, gm.y - 6).stroke({ color: AC, width: 2.6 });
      triR(g, rn.x - 20, gm.y - 6, 9, AC);
      lbl(g, (n.x + rn.x) / 2, gm.up.y - 12, 'x.right', AC, 13);
    } else {
      g.rect(gm.up.w, gm.up.h).move(gm.up.x, gm.up.y).radius(gm.up.r)
        .fill('none').stroke({ color: AC, width: 2.6 });
      if (rn) triR(g, rn.x - 20, gm.y - 6, 9, AC);
      lbl(g, gm.up.x + gm.up.w / 2, gm.up.y - 12, 'x.right (wraps to the first sibling)', AC, 13);
    }
    var lnb = byId(grp[(i - 1 + len) % len]);
    if (i > 0 && lnb) {
      g.line(n.x - 20, gm.y + 6, lnb.x + 28, gm.y + 6).stroke({ color: AC, width: 2.6 });
      triL(g, lnb.x + 20, gm.y + 6, 9, AC);
      lbl(g, (n.x + lnb.x) / 2, gm.lo.y + gm.lo.h + 12, 'x.left', AC, 13);
    } else {
      g.rect(gm.lo.w, gm.lo.h).move(gm.lo.x, gm.lo.y).radius(gm.lo.r)
        .fill('none').stroke({ color: AC, width: 2.6 });
      if (lnb) triL(g, lnb.x + 20, gm.y + 6, 9, AC);
      lbl(g, gm.lo.x + gm.lo.w / 2, gm.lo.y + gm.lo.h + 12, 'x.left (wraps to the last sibling)', AC, 13);
    }
  }

  /* ---------- render ---------- */
  function render() {
    fadeEls = [];
    draw.clear();
    draw.rect(W, H).fill('#fff').on('click', function () { selectNode(null); });
    var gA = draw.group(), gB = draw.group();
    gB.translate(0, OY);
    drawA(gA);
    drawB(gB);
    gA.opacity(state.mode === 'b' ? 0.12 : 1);
    gB.opacity(state.mode === 'a' ? 0.12 : 1);
    gA.css('pointer-events', state.mode === 'b' ? 'none' : 'auto');
    gB.css('pointer-events', state.mode === 'a' ? 'none' : 'auto');
    if (state.fade) {
      fadeEls.forEach(function (e) { e.opacity(0); e.animate(420).opacity(1); });
      state.fade = false;
    }
  }

  /* ---------- selection ---------- */
  function selectNode(id) {
    state.selected = id;
    render();
    if (id == null) { hidePopup(); return; }
    var n = byId(id);
    if (!n) return;
    var grp = siblingGroupOf(id), i = grp.indexOf(id), len = grp.length;
    var rid = grp[(i + 1) % len], lid = grp[(i - 1 + len) % len];
    var cid = (n.id === 'new') ? null : CHILDPTR[n.id];
    var rk = byId(rid) ? byId(rid).k : n.k, lk = byId(lid) ? byId(lid).k : n.k;
    var body = 'x.p = ' + (n.p == null ? 'NIL (it is a root)' : n.p) +
      ' · x.child = ' + (cid == null ? 'NIL' : cid + ' (the other children are reached through that child\'s circular sibling list)') +
      ' · x.left = ' + lk + ' · x.right = ' + rk +
      (len === 1 ? '. A lone node\'s left and right both point at itself.' : '.') +
      ' Those four pointers plus degree and mark are the entire node record — which is why splicing a tree in or out of a list is O(1).';
    showPopup('Node ' + n.k + ' — its four pointers', body);
  }

  /* ---------- status / insert ---------- */
  function setStatus(msg) {
    var el = document.getElementById('insertStatus');
    if (el) el.textContent = msg;
  }
  function compareMsg() {
    return state.key < 3
      ? '3. Compare: key ' + state.key + ' < 3 → H.min ← x. One comparison, then done. Total work: O(1); no trees are consolidated.'
      : '3. Compare: key ' + state.key + ' > 3 → H.min stays at 3. Total work: O(1); no trees are consolidated.';
  }
  function clearInsert() {
    state.inserted = false;
    state.phase = 0;
    setStatus('Click any node to inspect its four pointer fields, or run FIB-HEAP-INSERT.');
  }
  function doInsertInstant() {
    state.inserted = true;
    state.phase = 3;
    setStatus(compareMsg());
  }

  /* ---------- global control handlers ---------- */
  window.update_viewToggle = function (v) {
    state.mode = v;
    render();
  };
  window.update_insertKey = function (v) {
    state.key = v;
    if (state.inserted && state.phase >= 3) setStatus(compareMsg());
    render();
  };
  window.trigger_reset = function () {
    if (running) return;
    clearInsert();
    state.selected = null;
    render();
  };
  window.trigger_insertAnim = function () {
    if (running) return;
    running = true;
    state.selected = null;
    clearInsert();
    state.inserted = true;
    state.phase = 1;
    state.fade = true;
    render();
    setStatus('1. Allocate node x: key = ' + state.key +
      ', degree 0, x.p = x.child = NIL, mark = FALSE, and x.left = x.right = x — its own one-element circular list.');
    setTimeout(function () {
      state.phase = 2;
      state.fade = true;
      render();
      setStatus('2. Splice x into the root list between 24 and 23 — exactly four assignments: x.left = 24, x.right = 23, 24.right = x, 23.left = x. The heap size never enters into it.');
      setTimeout(function () {
        state.phase = 3;
        state.fade = true;
        render();
        setStatus(compareMsg());
        running = false;
      }, 1500);
    }, 1500);
  };

  /* ---------- demo step player ---------- */
  function setMode(m) {
    state.mode = m;
    var el = document.getElementById('viewToggleInput');
    if (el) el.value = m;
  }
  function setKey(k) {
    state.key = k;
    var i = document.getElementById('insertKeyInput');
    if (i) i.value = k;
    var o = document.getElementById('insertKeyVal');
    if (o) o.value = k;
  }

  var steps = [
    {
      t: 'The abstract view',
      n: 'Five min-heap-ordered trees hang off a root list drawn as a dashed line, with H.min pointing at the smallest root, 3. Black nodes (18, 39, 26) are marked — each has lost one child since it last became a child.',
      f: function () { setMode('both'); clearInsert(); state.selected = null; }
    },
    {
      t: 'What the dashed line really is',
      n: 'Switch to the pointer diagram: the dashed root line becomes a circular doubly linked list, and every group of siblings — 18/52/38, 26/46, and each lone child — is its own circular list with forward and backward arrows.',
      f: function () { setMode('b'); clearInsert(); state.selected = null; }
    },
    {
      t: 'One node, four pointers',
      n: 'Node 18 is highlighted: its p, child, left and right fields light up. Click any other node to inspect it — 39, an only child, has left = right = itself, and 52 has no child pointer at all.',
      f: function () { setMode('b'); clearInsert(); state.selected = 18; }
    },
    {
      t: 'Insert a key larger than the minimum',
      n: 'Insert 21: a new single-node tree is spliced into the root list by rewiring just four pointers. Because 21 > 3, H.min does not move and nothing is consolidated.',
      f: function () { setMode('b'); state.selected = null; setKey(21); doInsertInstant(); }
    },
    {
      t: 'Insert a new minimum',
      n: 'Insert 2 instead: the splice is identical — same four pointer updates — but the single key comparison now succeeds and H.min swings to the new root. Insert is O(1) either way.',
      f: function () { setMode('b'); state.selected = null; setKey(2); doInsertInstant(); }
    },
    {
      t: 'Back to the abstraction',
      n: 'Both views together, with the new root in place. The abstract picture hides the pointers, but knowing they are circular doubly linked lists is exactly why splicing, cutting and melding are constant time.',
      f: function () { setMode('both'); state.selected = null; setKey(2); doInsertInstant(); }
    }
  ];
  var cur = 0;

  function applyStep(i) {
    if (running) return;
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    s.f();
    state.fade = true;
    render();
    var nar = document.getElementById('demoNarration');
    if (nar) nar.textContent = s.n;
    var lab = document.getElementById('stepLabel');
    if (lab) lab.textContent = 'Step ' + (cur + 1) + '/' + steps.length + ' — ' + s.t;
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  /* ---------- init ---------- */
  setStatus('Click any node to inspect its four pointer fields, or run FIB-HEAP-INSERT.');
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END
